/**
 * La phrase dans la langue demandee. Retombe sur l anglais si la traduction
 * manque : une phrase dans la mauvaise langue reste une phrase, alors qu une
 * chaine vide efface l ecran.
 *
 * Une CLEF inconnue est renvoyee telle quelle — meme choix que perso(). C est
 * un bug de code, pas de traduction, et il doit se voir.
 */
export function recit(cle: string, locale: Locale): string {
  const r = RECITS[cle];
  if (!r) {
    // Une clef absente ne s AFFICHE JAMAIS.
    //
    // Cette ligne rendait `cle`. Les clefs etant construites a la volee —
    // `domaine.${temps}.${maison}`, `action.${t}.${maison}` — il suffisait
    // qu une combinaison manque pour que le paragraphe d ouverture de la fiche
    // affiche litteralement « domaine.passe.7 ». C est le motif recurrent nº 1
    // du depot : l echec silencieux qui ressort comme du contenu.
    //
    // On rend une chaine vide, conformement a la regle du produit — quand une
    // donnee manque, on n affiche rien — et on crie fort en developpement, ou
    // quelqu un peut encore le voir.
    if (process.env.NODE_ENV !== "production") {
      console.error(`[recits] clef absente : ${cle}`);
    }
    return "";
  }
  return r[locale] || r.en;
}

/**
 * La phrase, avec ses emplacements remplis.
 *
 * Les emplacements sont nommes ({planete}, {n}, {total}) et non positionnels :
 * chaque langue les met dans SON ordre. C est tout l interet par rapport a une
 * concatenation, qui imposait l ordre des mots du francais aux dix langues.
 */
export function recitAvec(cle: string, locale: Locale, valeurs: Record<string, string | number>): string {
  let texte = recit(cle, locale);
  for (const [nom, valeur] of Object.entries(valeurs)) {
    texte = texte.split(`{${nom}}`).join(String(valeur));
  }
  return texte;
}

/** Ce que le controle de completude compte. */
export const CLES_RECITS = Object.keys(RECITS);
